import json


def deep_merge(a, b):
    if isinstance(a, dict) and isinstance(b, dict):
        result = {}
        for key in a:
            if key in b:
                result[key] = deep_merge(a[key], b[key])
            else:
                result[key] = a[key]
        for key in b:
            if key not in a:
                result[key] = b[key]
        return result
    elif isinstance(a, list) and isinstance(b, list):
        seen = []
        for item in a:
            if item not in seen:
                seen.append(item)
        for item in b:
            if item not in seen:
                seen.append(item)
        return seen
    else:
        return b


def main():
    with open('<tmp>') as f:
        a = json.load(f)
    with open('<tmp>') as f:
        b = json.load(f)

    merged = deep_merge(a, b)
    print(json.dumps(merged, sort_keys=True, indent=2))


main()

