import Foundation

let filePath = "<tmp>"

let content = try String(contentsOfFile: filePath, encoding: .utf8)
let lines = content.components(separatedBy: "\n").filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }

var levelCounts: [String: Int] = [:]
var errorComponentCounts: [String: Int] = [:]
var errorMessages: Set<String> = []
var hourCounts: [String: Int] = [:]

let pattern = "^\\[\\d{4}-\\d{2}-\\d{2} (\\d{2}):\\d{2}:\\d{2}\\] (\\w+) \\(([^)]+)\\) - (.+)$"
let regex = try NSRegularExpression(pattern: pattern)

for line in lines {
    let range = NSRange(line.startIndex..., in: line)
    guard let match = regex.firstMatch(in: line, range: range) else { continue }

    let hour = String(line[Range(match.range(at: 1), in: line)!])
    let level = String(line[Range(match.range(at: 2), in: line)!])
    let component = String(line[Range(match.range(at: 3), in: line)!])
    let message = String(line[Range(match.range(at: 4), in: line)!])

    levelCounts[level, default: 0] += 1

    if level == "ERROR" {
        errorComponentCounts[component, default: 0] += 1
        errorMessages.insert(message)
    }

    hourCounts[hour, default: 0] += 1
}

print("=== Log Analysis ===")
print("")
print("Entries by Level:")
for level in levelCounts.keys.sorted() {
    print("  \(level): \(levelCounts[level]!)")
}
print("")
if let top = errorComponentCounts.max(by: { $0.value < $1.value }) {
    print("Component with Most Errors: \(top.key) (\(top.value) errors)")
}
print("")
print("Unique Error Messages:")
for msg in errorMessages.sorted() {
    print("  - \(msg)")
}
print("")
if let top = hourCounts.max(by: { $0.value < $1.value }) {
    print("Busiest Hour: \(top.key):00 (\(top.value) entries)")
}

