import * as fs from 'fs';

const logPath = '<tmp>';
const content: string = fs.readFileSync(logPath, 'utf-8');
const lines: string[] = content.split('\n').filter(line => line.trim() !== '');

const levelCounts: Map<string, number> = new Map();
const errorComponentCounts: Map<string, number> = new Map();
const errorMessages: Set<string> = new Set();
const hourCounts: Map<string, number> = new Map();

const regex = /^\[(\d{4}-\d{2}-\d{2}) (\d{2}):(\d{2}):(\d{2})\] (\S+) \(([^)]+)\) - (.+)$/;

for (const line of lines) {
    const match = line.match(regex);
    if (!match) continue;

    const hour: string = match[2];
    const level: string = match[5];
    const component: string = match[6];
    const message: string = match[7];

    levelCounts.set(level, (levelCounts.get(level) || 0) + 1);
    hourCounts.set(hour, (hourCounts.get(hour) || 0) + 1);

    if (level === 'ERROR') {
        errorComponentCounts.set(component, (errorComponentCounts.get(component) || 0) + 1);
        errorMessages.add(message);
    }
}

let output: string = '';
output += '=== Log Analysis ===\n';
output += '\n';
output += 'Entries by Level:\n';

const sortedLevels: string[] = Array.from(levelCounts.keys()).sort();
for (const level of sortedLevels) {
    output += `  ${level}: ${levelCounts.get(level)}\n`;
}

output += '\n';

let maxErrors: number = 0;
let maxComponent: string = '';
for (const [comp, count] of errorComponentCounts) {
    if (count > maxErrors) {
        maxErrors = count;
        maxComponent = comp;
    }
}
output += `Component with Most Errors: ${maxComponent} (${maxErrors} errors)\n`;

output += '\n';
output += 'Unique Error Messages:\n';
const sortedMessages: string[] = Array.from(errorMessages).sort();
for (const msg of sortedMessages) {
    output += `  - ${msg}\n`;
}

output += '\n';

let maxEntries: number = 0;
let busiestHour: string = '';
for (const [hour, count] of hourCounts) {
    if (count > maxEntries) {
        maxEntries = count;
        busiestHour = hour;
    }
}
output += `Busiest Hour: ${busiestHour}:00 (${maxEntries} entries)\n`;

process.stdout.write(output);

