import json
import heapq

def main():
    with open("<tmp>", "r") as f:
        data = json.load(f)

    nodes = data["nodes"]
    edges = data["edges"]

    adj = {node: [] for node in nodes}
    for edge in edges:
        u = edge["from"]
        v = edge["to"]
        w = edge["weight"]
        adj[u].append((v, w))
        adj[v].append((u, w))

    INF = float('inf')
    dist = {node: INF for node in nodes}
    dist["A"] = 0

    pq = [(0, "A")]

    while pq:
        d, u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v, w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq, (nd, v))

    print("=== Shortest Paths from A ===")
    print()
    for node in sorted(nodes):
        d = dist[node]
        if d == INF:
            print(f"A -> {node}: unreachable")
        else:
            if isinstance(d, float) and d == int(d):
                d = int(d)
            print(f"A -> {node}: {d}")

main()

