#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

#define MAX_NAME 256

typedef struct {
    char name[MAX_NAME];
    double salary;
} Employee;

typedef struct {
    char name[MAX_NAME];
    double total_salary;
    int count;
} Dept;

int compare_depts(const void *a, const void *b) {
    return strcmp(((const Dept *)a)->name, ((const Dept *)b)->name);
}

void format_int_with_commas(long long n, char *buf) {
    int neg = 0;
    if (n < 0) { neg = 1; n = -n; }
    char tmp[32];
    int len = 0;
    if (n == 0) {
        tmp[len++] = '0';
    } else {
        while (n > 0) {
            tmp[len++] = '0' + (int)(n % 10);
            n /= 10;
        }
    }
    for (int i = 0; i < len / 2; i++) {
        char t = tmp[i]; tmp[i] = tmp[len - 1 - i]; tmp[len - 1 - i] = t;
    }
    int pos = 0;
    if (neg) buf[pos++] = '-';
    for (int i = 0; i < len; i++) {
        buf[pos++] = tmp[i];
        if (i < len - 1 && (len - 1 - i) % 3 == 0) {
            buf[pos++] = ',';
        }
    }
    buf[pos] = '\0';
}

void format_avg(double val, char *buf) {
    long long cents = (long long)(val * 100.0 + 0.5);
    long long ip = cents / 100;
    int dp = (int)(cents % 100);
    char intbuf[32];
    format_int_with_commas(ip, intbuf);
    sprintf(buf, "%s.%02d", intbuf, dp);
}

int main(void) {
    const char *path = "<tmp>";
    FILE *f = fopen(path, "r");
    if (!f) {
        perror("fopen");
        return 1;
    }

    Employee *emps = NULL;
    int emp_count = 0, emp_cap = 0;
    Dept *depts = NULL;
    int dept_count = 0, dept_cap = 0;

    char line[4096];
    int first_line = 1;

    while (fgets(line, sizeof(line), f)) {
        line[strcspn(line, "\r\n")] = '\0';
        if (first_line) { first_line = 0; continue; }
        if (line[0] == '\0') continue;

        char *fields[6];
        int nf = 0;
        char *p = line;
        while (nf < 6) {
            fields[nf++] = p;
            p = strchr(p, ',');
            if (p) *p++ = '\0';
            else break;
        }
        if (nf < 4) continue;

        if (emp_count == emp_cap) {
            emp_cap = emp_cap ? emp_cap * 2 : 128;
            emps = (Employee *)realloc(emps, (size_t)emp_cap * sizeof(Employee));
            if (!emps) { perror("realloc"); return 1; }
        }
        strncpy(emps[emp_count].name, fields[1], MAX_NAME - 1);
        emps[emp_count].name[MAX_NAME - 1] = '\0';
        emps[emp_count].salary = atof(fields[3]);
        emp_count++;

        int found = -1;
        for (int i = 0; i < dept_count; i++) {
            if (strcmp(depts[i].name, fields[2]) == 0) { found = i; break; }
        }
        if (found == -1) {
            if (dept_count == dept_cap) {
                dept_cap = dept_cap ? dept_cap * 2 : 64;
                depts = (Dept *)realloc(depts, (size_t)dept_cap * sizeof(Dept));
                if (!depts) { perror("realloc"); return 1; }
            }
            strncpy(depts[dept_count].name, fields[2], MAX_NAME - 1);
            depts[dept_count].name[MAX_NAME - 1] = '\0';
            depts[dept_count].total_salary = 0.0;
            depts[dept_count].count = 0;
            found = dept_count++;
        }
        depts[found].total_salary += atof(fields[3]);
        depts[found].count++;
    }
    fclose(f);

    qsort(depts, (size_t)dept_count, sizeof(Dept), compare_depts);

    int highest_idx = 0;
    for (int i = 1; i < emp_count; i++) {
        if (emps[i].salary > emps[highest_idx].salary) highest_idx = i;
    }

    long long total_budget = 0;
    for (int i = 0; i < emp_count; i++) {
        total_budget += (long long)(emps[i].salary + 0.5);
    }

    char buf[64];

    printf("=== Salary Report ===\n");
    printf("\n");
    printf("Average Salary by Department:\n");
    for (int i = 0; i < dept_count; i++) {
        double avg = depts[i].total_salary / (double)depts[i].count;
        format_avg(avg, buf);
        printf("  %s: $%s\n", depts[i].name, buf);
    }
    printf("\n");
    printf("Highest Paid: ");
    printf("%s ($", emps[highest_idx].name);
    format_int_with_commas((long long)(emps[highest_idx].salary + 0.5), buf);
    printf("%s)\n", buf);
    printf("\n");
    printf("Departments with >2 employees:\n");
    for (int i = 0; i < dept_count; i++) {
        if (depts[i].count > 2) {
            printf("  %s (%d employees)\n", depts[i].name, depts[i].count);
        }
    }
    printf("\n");
    printf("Total Budget: $");
    format_int_with_commas(total_budget, buf);
    printf("%s\n", buf);

    free(emps);
    free(depts);
    return 0;
}
