        conn.setRequestMethod("GET");
        conn.setConnectTimeout(10000);
        conn.setReadTimeout(10000);

        BufferedReader reader = new BufferedReader(new InputStreamReader(conn.getInputStream()));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            sb.append(line);
        }
        reader.close();
        conn.disconnect();
        String json = sb.toString();

        List<String[]> products = new ArrayList<>();
        int i = 0;
        while (i < json.length()) {
            int start = json.indexOf('{', i);
            if (start == -1) break;
            int end = json.indexOf('}', start);
            if (end == -1) break;
            String obj = json.substring(start, end + 1);
            String name = extractString(obj, "name");
            double price = extractNumber(obj, "price");
            products.add(new String[]{name, String.valueOf(price)});
            i = end + 1;
        }

        List<String[]> filtered = new ArrayList<>();
        for (String[] p : products) {
            if (Double.parseDouble(p[1]) > 50.00) {
                filtered.add(p);
            }
        }

        filtered.sort((a, b) -> a[0].compareTo(b[0]));

        System.out.println("=== Filtered Products (price > $50.00) ===");
        System.out.println();
        double total = 0;
        for (String[] p : filtered) {
            double price = Double.parseDouble(p[1]);
            System.out.printf("%s: $%.2f%n", p[0], price);
            total += price;
        }
        System.out.println();
        System.out.println("Count: " + filtered.size());
        System.out.printf("Total: $%.2f%n", total);
    }

    static String extractString(String obj, String key) {
        String search = "\"" + key + "\"";
        int keyIdx = obj.indexOf(search);
        if (keyIdx == -1) return "";
        int colonIdx = obj.indexOf(':', keyIdx + search.length());
        int quoteStart = obj.indexOf('"', colonIdx + 1);
        int quoteEnd = obj.indexOf('"', quoteStart + 1);
        if (quoteStart == -1 || quoteEnd == -1) return "";
        return obj.substring(quoteStart + 1, quoteEnd);
    }

    static double extractNumber(String obj, String key) {
        String search = "\"" + key + "\"";
        int keyIdx = obj.indexOf(search);
        if (keyIdx == -1) return 0;
        int colonIdx = obj.indexOf(':', keyIdx + search.length());
        int numStart = colonIdx + 1;
        while (numStart < obj.length() && obj.charAt(numStart) == ' ') numStart++;
        int numEnd = numStart;
        while (numEnd < obj.length() && (Character.isDigit(obj.charAt(numEnd)) || obj.charAt(numEnd) == '.' || obj.charAt(numEnd) == '-' || obj.charAt(numEnd) == '+')) {
            numEnd++;
        }
        return Double.parseDouble(obj.substring(numStart, numEnd));
    }
}

