fn format_comma_integer(n: i64) -> String {
    let neg = n < 0;
    let s = n.abs().to_string();
    let len = s.len();
    let mut result = String::new();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    if neg {
        result.insert(0, '-');
    }
    result
}

fn format_comma_float(n: f64) -> String {
    let scaled = (n * 100.0).round() as i64;
    let int_part = scaled / 100;
    let frac_part = (scaled % 100).abs();
    format!("{}.{:02}", format_comma_integer(int_part), frac_part)
}

