fn format_comma_integer(n: i64) -> String {
    let neg = n < 0;
    let s = n.abs().to_string();
    let len = s.len();
    let mut result = String::new();
    for (i, c) in s.chars().enumerate() {
        if i > 0 && (len - i) % 3 == 0 {
            result.push(',');
        }
        result.push(c);
    }
    if neg {
        result.insert(0, '-');
    }
    result
}

fn format_comma_float(n: f64) -> String {
    let scaled = (n * 100.0).round() as i64;
    let int_part = scaled / 100;
    let frac_part = (scaled % 100).abs();
    format!("{}.{:02}", format_comma_integer(int_part), frac_part)
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read file");

    let lines: Vec<&str> = content.lines().collect();
    let mut dept_salaries: HashMap<String, Vec<f64>> = HashMap::new();
    let mut max_salary: f64 = f64::MIN;
    let mut max_name: String = String::new();
    let mut total_budget: f64 = 0.0;

    for (i, line) in lines.iter().enumerate() {
        if i == 0 {
            continue;
        }
        if line.trim().is_empty() {
            continue;
        }

        let fields: Vec<&str> = line.split(',').collect();
        if fields.len() < 6 {
            continue;
        }

        let name = fields[1].trim().to_string();
        let department = fields[2].trim().to_string();
        let salary: f64 = fields[3].trim().parse().expect("Failed to parse salary");

        dept_salaries.entry(department).or_insert_with(Vec::new).push(salary);
        total_budget += salary;

        if salary > max_salary {
            max_salary = salary;
            max_name = name;
        }
    }

    let mut depts: Vec<String> = dept_salaries.keys().cloned().collect();
    depts.sort();

    println!("=== Salary Report ===");
    println!();
    println!("Average Salary by Department:");
    for dept in &depts {
        let salaries = &dept_salaries[dept];
        let avg = salaries.iter().sum::<f64>() / salaries.len() as f64;
        println!("  {}: ${}", dept, format_comma_float(avg));
    }
    println!();
    println!("Highest Paid: {} (${})", max_name, format_comma_integer(max_salary.round() as i64));
    println!();
    println!("Departments with >2 employees:");
    for dept in &depts {
        let count = dept_salaries[dept].len();
        if count > 2 {
            println!("  {} ({} employees)", dept, count);
        }
    }
    println!();
    println!("Total Budget: ${}", format_comma_integer(total_budget.round() as i64));
}

