import java.io.*;
import java.util.*;
import java.util.regex.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String path = "<tmp>";
        StringBuilder sb = new StringBuilder();
        BufferedReader br = new BufferedReader(new FileReader(path));
        String line;
        while ((line = br.readLine()) != null) {
            sb.append(line).append("\n");
        }
        br.close();
        String json = sb.toString();

        // Parse nodes
        List<String> nodes = new ArrayList<>();
        Matcher nodeArr = Pattern.compile("\"nodes\"\\s*:\\s*\\[([^\\]]*)\\]").matcher(json);
        if (nodeArr.find()) {
            String inner = nodeArr.group(1);
            Matcher nm = Pattern.compile("\"((?:[^\"\\\\]|\\\\.)*)\"").matcher(inner);
            while (nm.find()) {
                nodes.add(nm.group(1));
            }
        }

        // Parse edges
        List<String[]> edgeList = new ArrayList<>();
        Matcher edgeArr = Pattern.compile("\"edges\"\\s*:\\s*\\[([^\\]]*(?:\\[[^\\]]*\\][^\\]]*)*)\\]").matcher(json);
        String edgesBlock = "";
        if (edgeArr.find()) {
            edgesBlock = edgeArr.group(1);
        } else {
            // fallback: find all edge objects
            edgesBlock = json;
        }
        Matcher edgeObj = Pattern.compile("\\{([^{}]*)\\}").matcher(edgesBlock);
        while (edgeObj.find()) {
            String obj = edgeObj.group(1);
            if (obj.contains("\"from\"") && obj.contains("\"to\"") && obj.contains("\"weight\"")) {
                String from = extractStr(obj, "from");
                String to = extractStr(obj, "to");
                long weight = extractLong(obj, "weight");
                edgeList.add(new String[]{from, to, String.valueOf(weight)});
            }
        }

        // Build adjacency list (undirected)
        Map<String, List<String[]>> adj = new HashMap<>();
        for (String node : nodes) {
            adj.put(node, new ArrayList<>());
        }
        for (String[] e : edgeList) {
            adj.computeIfAbsent(e[0], k -> new ArrayList<>()).add(new String[]{e[1], e[2]});
            adj.computeIfAbsent(e[1], k -> new ArrayList<>()).add(new String[]{e[0], e[2]});
        }

        // Dijkstra's algorithm
        Map<String, Long> dist = new HashMap<>();
        for (String node : nodes) {
            dist.put(node, Long.MAX_VALUE);
        }
        dist.put("A", 0L);

        PriorityQueue<Object[]> pq = new PriorityQueue<>((a, b) -> Long.compare((Long) a[0], (Long) b[0]));
        pq.add(new Object[]{0L, "A"});

        while (!pq.isEmpty()) {
            Object[] curr = pq.poll();
            long d = (Long) curr[0];
            String u = (String) curr[1];
            if (d > dist.get(u)) continue;
            List<String[]> neighbors = adj.get(u);
            if (neighbors == null) continue;
            for (String[] nb : neighbors) {
                String v = nb[0];
                long w = Long.parseLong(nb[1]);
                long nd = d + w;
                if (nd < dist.get(v)) {
                    dist.put(v, nd);
                    pq.add(new Object[]{nd, v});
                }
            }
        }

        // Output
        System.out.println("=== Shortest Paths from A ===");
        System.out.println();
        List<String> sorted = new ArrayList<>(nodes);
        Collections.sort(sorted);
        for (String node : sorted) {
            long d = dist.get(node);
            if (d == Long.MAX_VALUE) {
                System.out.println("A -> " + node + ": unreachable");
            } else {
                System.out.println("A -> " + node + ": " + d);
            }
        }
    }

    static String extractStr(String s, String key) {
        Matcher m = Pattern.compile("\"" + key + "\"\\s*:\\s*\"((?:[^\"\\\\]|\\\\.)*)\"").matcher(s);
        if (m.find()) return m.group(1);
        return "";
    }

    static long extractLong(String s, String key) {
        Matcher m = Pattern.compile("\"" + key + "\"\\s*:\\s*(-?\\d+)").matcher(s);
        if (m.find()) return Long.parseLong(m.group(1));
        return 0;
    }
}

