#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char *name;
    int count;
} NameCount;

static int cmp_namecount(const void *a, const void *b) {
    const NameCount *x = (const NameCount *)a;
    const NameCount *y = (const NameCount *)b;
    return strcmp(x->name, y->name);
}

static int cmp_charptr(const void *a, const void *b) {
    const char *const *x = (const char *const *)a;
    const char *const *y = (const char *const *)b;
    return strcmp(*x, *y);
}

int main(void) {
    const char *path = "<tmp>";
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Cannot open file\n");
        return 1;
    }

    NameCount *levels = NULL;
    int nlevels = 0, caplevels = 0;

    NameCount *err_comps = NULL;
    int nerr_comps = 0, caperr_comps = 0;

    char **err_msgs = NULL;
    int nerr_msgs = 0, caperr_msgs = 0;

    int *hours = (int *)calloc(24, sizeof(int));
    if (!hours) { fclose(fp); return 1; }

    char *line = (char *)malloc(8192);
    if (!line) { fclose(fp); free(hours); return 1; }

    while (fgets(line, 8192, fp)) {
        size_t len = strlen(line);
        if (len > 0 && line[len - 1] == '\n') line[len - 1] = '\0';
        if (len < 22) continue;

        if (line[0] != '[') continue;

        int hour = -1;
        if (line[12] >= '0' && line[12] <= '9' && line[13] >= '0' && line[13] <= '9') {
            hour = (line[12] - '0') * 10 + (line[13] - '0');
        }
        if (hour >= 0 && hour < 24) hours[hour]++;

        char *p = strchr(line, ']');
        if (!p) continue;
        char *after = p + 1;
        if (*after == ' ') after++;

        char *space = strchr(after, ' ');
        if (!space) continue;
        *space = '\0';
        char *level = after;

        char *after_level = space + 1;
        char *open_p = strchr(after_level, '(');
        char *close_p = strchr(after_level, ')');
        if (!open_p || !close_p || close_p < open_p) continue;

        char *component = open_p + 1;
        *close_p = '\0';

        char *after_close = close_p + 1;
        if (strncmp(after_close, " - ", 3) != 0) continue;
        char *message = after_close + 3;

        /* Count level */
        int found = 0;
        for (int i = 0; i < nlevels; i++) {
            if (strcmp(levels[i].name, level) == 0) {
                levels[i].count++;
                found = 1;
                break;
            }
        }
        if (!found) {
            if (nlevels == caplevels) {
                caplevels = caplevels == 0 ? 16 : caplevels * 2;
                levels = (NameCount *)realloc(levels, caplevels * sizeof(NameCount));
                if (!levels) { fclose(fp); free(line); free(hours); return 1; }
            }
            levels[nlevels].name = strdup(level);
            levels[nlevels].count = 1;
            nlevels++;
        }

        /* If ERROR, track component and message */
        if (strcmp(level, "ERROR") == 0) {
            found = 0;
            for (int i = 0; i < nerr_comps; i++) {
                if (strcmp(err_comps[i].name, component) == 0) {
                    err_comps[i].count++;
                    found = 1;
                    break;
                }
            }
            if (!found) {
                if (nerr_comps == caperr_comps) {
                    caperr_comps = caperr_comps == 0 ? 16 : caperr_comps * 2;
                    err_comps = (NameCount *)realloc(err_comps, caperr_comps * sizeof(NameCount));
                    if (!err_comps) { fclose(fp); free(line); free(hours); return 1; }
                }
                err_comps[nerr_comps].name = strdup(component);
                err_comps[nerr_comps].count = 1;
                nerr_comps++;
            }

            int is_unique = 1;
            for (int i = 0; i < nerr_msgs; i++) {
                if (strcmp(err_msgs[i], message) == 0) {
                    is_unique = 0;
                    break;
                }
            }
            if (is_unique) {
                if (nerr_msgs == caperr_msgs) {
                    caperr_msgs = caperr_msgs == 0 ? 16 : caperr_msgs * 2;
                    err_msgs = (char **)realloc(err_msgs, caperr_msgs * sizeof(char *));
                    if (!err_msgs) { fclose(fp); free(line); free(hours); return 1; }
                }
                err_msgs[nerr_msgs] = strdup(message);
                nerr_msgs++;
            }
        }
    }

    fclose(fp);
    free(line);

    /* Sort levels alphabetically */
    if (nlevels > 1) qsort(levels, nlevels, sizeof(NameCount), cmp_namecount);

    /* Sort error messages alphabetically */
    if (nerr_msgs > 1) qsort(err_msgs, nerr_msgs, sizeof(char *), cmp_charptr);

    /* Find component with most errors */
    int best_comp_idx = -1;
    int best_comp_count = 0;
    for (int i = 0; i < nerr_comps; i++) {
        if (err_comps[i].count > best_comp_count ||
            (err_comps[i].count == best_comp_count && best_comp_idx >= 0 &&
             strcmp(err_comps[i].name, err_comps[best_comp_idx].name) < 0)) {
            best_comp_count = err_comps[i].count;
            best_comp_idx = i;
        }
    }

    /* Find busiest hour */
    int best_hour = 0;
    int best_hour_count = 0;
    for (int h = 0; h < 24; h++) {
        if (hours[h] > best_hour_count) {
            best_hour_count = hours[h];
            best_hour = h;
        }
    }

    /* Print output */
    printf("=== Log Analysis ===\n");
    printf("\n");
    printf("Entries by Level:\n");
    for (int i = 0; i < nlevels; i++) {
        printf("  %s: %d\n", levels[i].name, levels[i].count);
    }
    printf("\n");
    if (best_comp_idx >= 0) {
        printf("Component with Most Errors: %s (%d errors)\n", err_comps[best_comp_idx].name, err_comps[best_comp_idx].count);
    } else {
        printf("Component with Most Errors: N/A (0 errors)\n");
    }
    printf("\n");
    printf("Unique Error Messages:\n");
    for (int i = 0; i < nerr_msgs; i++) {
        printf("  - %s\n", err_msgs[i]);
    }
    printf("\n");
    printf("Busiest Hour: %02d:00 (%d entries)\n", best_hour, best_hour_count);

    /* Cleanup */
    for (int i = 0; i < nlevels; i++) free(levels[i].name);
    free(levels);
    for (int i = 0; i < nerr_comps; i++) free(err_comps[i].name);
    free(err_comps);
    for (int i = 0; i < nerr_msgs; i++) free(err_msgs[i]);
    free(err_msgs);
    free(hours);

    return 0;
}

