    if (c == 'f') { p->pos += 5; return json_new_bool(0); }
    if (c == 'n') { p->pos += 4; return json_new_null(); }
    return parse_number(p);
}

static int json_equal(JsonValue *a, JsonValue *b) {
    if (a->type != b->type) return 0;
    switch (a->type) {
        case JSON_NULL: return 1;
        case JSON_BOOL: return a->bool_val == b->bool_val;
        case JSON_NUMBER: return a->num_val == b->num_val;
        case JSON_STRING: return strcmp(a->str_val, b->str_val) == 0;
        case JSON_ARRAY: {
            if (a->arr_count != b->arr_count) return 0;
            for (int i = 0; i < a->arr_count; i++) {
                if (!json_equal(a->arr_items[i], b->arr_items[i])) return 0;
            }
            return 1;
        }
        case JSON_OBJECT: {
            if (a->obj_count != b->obj_count) return 0;
            for (int i = 0; i < a->obj_count; i++) {
                int found = 0;
                for (int j = 0; j < b->obj_count; j++) {
                    if (strcmp(a->obj_pairs[i].key, b->obj_pairs[j].key) == 0) {
                        if (!json_equal(a->obj_pairs[i].value, b->obj_pairs[j].value)) return 0;
                        found = 1;
                        break;
                    }
                }
                if (!found) return 0;
            }
            return 1;
        }
    }
    return 0;
}

static JsonValue *deep_merge(JsonValue *a, JsonValue *b) {
    if (a->type == JSON_OBJECT && b->type == JSON_OBJECT) {
        JsonValue *result = json_new_object();
        /* Add all keys from A */
        for (int i = 0; i < a->obj_count; i++) {
            const char *key = a->obj_pairs[i].key;
            JsonValue *aval = a->obj_pairs[i].value;
            int found_in_b = -1;
            for (int j = 0; j < b->obj_count; j++) {
                if (strcmp(key, b->obj_pairs[j].key) == 0) {
                    found_in_b = j;
                    break;
                }
            }
            if (found_in_b >= 0) {
                JsonPair *existing = NULL;
                for (int k = 0; k < result->obj_count; k++) {
                    if (strcmp(result->obj_pairs[k].key, key) == 0) {
                        existing = &result->obj_pairs[k];
                        break;
                    }
                }
                if (existing) {
                    free(existing->value);
                    existing->value = deep_merge(aval, b->obj_pairs[found_in_b].value);
                } else {
                    json_object_set(result, key, deep_merge(aval, b->obj_pairs[found_in_b].value));
                }
            } else {
                json_object_set(result, key, aval);
            }
        }
        /* Add keys only in B */
        for (int j = 0; j < b->obj_count; j++) {
            const char *key = b->obj_pairs[j].key;
            int found_in_a = 0;
            for (int i = 0; i < a->obj_count; i++) {
                if (strcmp(key, a->obj_pairs[i].key) == 0) {
                    found_in_a = 1;
                    break;
                }
            }
            if (!found_in_a) {
                json_object_set(result, key, b->obj_pairs[j].value);
            }
        }
        return result;
    }
    if (a->type == JSON_ARRAY && b->type == JSON_ARRAY) {
        JsonValue *result = json_new_array();
        /* Add all items from A */
        for (int i = 0; i < a->arr_count; i++) {
            json_array_append(result, a->arr_items[i]);
        }
        /* Add items from B that are not already in result */
        for (int j = 0; j < b->arr_count; j++) {
            int dup = 0;
            for (int i = 0; i < result->arr_count; i++) {
                if (json_equal(result->arr_items[i], b->arr_items[j])) {
                    dup = 1;
                    break;
                }
            }
            if (!dup) {
                json_array_append(result, b->arr_items[j]);
            }
        }
        return result;
    }
    /* Scalar conflict or type mismatch: B overrides A */
    return b;
}

static void serialize_indent(int level, FILE *out) {
    for (int i = 0; i < level; i++) {
        fprintf(out, "  ");
    }
}

static void serialize_string_escaped(const char *str, FILE *out) {
    fputc('"', out);
    for (const char *p = str; *p; p++) {
        unsigned char c = (unsigned char)*p;
        switch (c) {
            case '"': fputs("\\\"", out); break;
            case '\\': fputs("\\\\", out); break;
            case '\b': fputs("\\b", out); break;
            case '\f': fputs("\\f", out); break;
            case '\n': fputs("\\n", out); break;
            case '\r': fputs("\\r", out); break;
            case '\t': fputs("\\t", out); break;
            default:
                if (c < 0x20) {
                    fprintf(out, "\\u%04x", c);
                } else {
                    fputc(c, out);
                }
        }
    }
    fputc('"', out);
}

static void serialize_number(JsonValue *v, FILE *out) {
    if (v->str_val) {
        fputs(v->str_val, out);
    } else {
        if (v->num_val == (long long)v->num_val && fabs(v->num_val) < 1e15) {
            fprintf(out, "%lld", (long long)v->num_val);
        } else {
            fprintf(out, "%g", v->num_val);
        }
    }
}

static void serialize(JsonValue *v, int level, FILE *out);

static int compare_pairs(const void *a, const void *b) {
    const JsonPair *pa = (const JsonPair *)a;
    const JsonPair *pb = (const JsonPair *)b;
    return strcmp(pa->key, pb->key);
}

static void serialize(JsonValue *v, int level, FILE *out) {
    switch (v->type) {
        case JSON_NULL:
            fprintf(out, "null");
            break;
        case JSON_BOOL:
            fprintf(out, v->bool_val ? "true" : "false");
            break;
        case JSON_NUMBER:
            serialize_number(v, out);
            break;
        case JSON_STRING:
            serialize_string_escaped(v->str_val, out);
            break;
        case JSON_ARRAY:
            if (v->arr_count == 0) {
                fprintf(out, "[]");
            } else {
                fprintf(out, "[\n");
                for (int i = 0; i < v->arr_count; i++) {
                    serialize_indent(level + 1, out);
                    serialize(v->arr_items[i], level + 1, out);
                    if (i < v->arr_count - 1) fputc(',', out);
                    fputc('\n', out);
                }
                serialize_indent(level, out);
                fprintf(out, "]");
            }
            break;
        case JSON_OBJECT:
            if (v->obj_count == 0) {
                fprintf(out, "{}");
            } else {
                /* Sort keys */
                qsort(v->obj_pairs, v->obj_count, sizeof(JsonPair), compare_pairs);
                fprintf(out, "{\n");
                for (int i = 0; i < v->obj_count; i++) {
                    serialize_indent(level + 1, out);
                    serialize_string_escaped(v->obj_pairs[i].key, out);
                    fprintf(out, ": ");
                    serialize(v->obj_pairs[i].value, level + 1, out);
                    if (i < v->obj_count - 1) fputc(',', out);
                    fputc('\n', out);
                }
                serialize_indent(level, out);
                fprintf(out, "}");
            }
            break;
    }
}

static char *read_file(const char *path) {
    FILE *f = fopen(path, "rb");
    if (!f) {
        fprintf(stderr, "Error: cannot open %s\n", path);
        exit(1);
    }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    char *buf = (char *)malloc(sz + 1);
    if (!buf) {
        fprintf(stderr, "Error: malloc failed\n");
        exit(1);
    }
    size_t rd = fread(buf, 1, sz, f);
    buf[rd] = '\0';
    fclose(f);
    return buf;
}

int main(void) {
    const char *path_a = "<tmp>";
    const char *path_b = "<tmp>";

    char *data_a = read_file(path_a);
    char *data_b = read_file(path_b);

    Parser pa = { data_a, 0, (int)strlen(data_a) };
    Parser pb = { data_b, 0, (int)strlen(data_b) };

    JsonValue *va = parse_value(&pa);
    JsonValue *vb = parse_value(&pb);

    JsonValue *merged = deep_merge(va, vb);

    serialize(merged, 0, stdout);
    fputc('\n', stdout);

    return 0;
}
