use std::collections::HashMap;
use std::fs;

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read log file");

    let mut level_counts: HashMap<String, usize> = HashMap::new();
    let mut error_component_counts: HashMap<String, usize> = HashMap::new();
    let mut error_messages: Vec<String> = Vec::new();
    let mut hour_counts: HashMap<u32, usize> = HashMap::new();

    for line in content.lines() {
        if line.trim().is_empty() {
            continue;
        }

        let bracket_end = line.find(']').unwrap();
        let timestamp = &line[1..bracket_end];

        let rest = &line[bracket_end + 2..];

        let paren_pos = rest.find('(').unwrap();
        let level = rest[..paren_pos].trim().to_string();

        let after_open_paren = &rest[paren_pos + 1..];
        let close_paren_pos = after_open_paren.find(')').unwrap();
        let component = after_open_paren[..close_paren_pos].trim().to_string();

        let after_close_paren = &after_open_paren[close_paren_pos + 1..];
        let message = after_close_paren.trim_start_matches(" - ").to_string();

        *level_counts.entry(level.clone()).or_insert(0) += 1;

        let hour_str = &timestamp[11..13];
        let hour: u32 = hour_str.parse().unwrap();
        *hour_counts.entry(hour).or_insert(0) += 1;

        if level == "ERROR" {
            *error_component_counts.entry(component.clone()).or_insert(0) += 1;
            if !error_messages.contains(&message) {
                error_messages.push(message);
            }
        }
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    let mut levels: Vec<&String> = level_counts.keys().collect();
    levels.sort();
    for level in &levels {
        println!("  {}: {}", level, level_counts[level]);
    }
    println!();

    let mut comps: Vec<(&String, &usize)> = error_component_counts.iter().collect();
    comps.sort_by(|a, b| b.1.cmp(a.1).then(a.0.cmp(b.0)));
    if let Some((comp, count)) = comps.first() {
        println!("Component with Most Errors: {} ({} errors)", comp, count);
    } else {
        println!("Component with Most Errors: N/A (0 errors)");
    }
    println!();

    println!("Unique Error Messages:");
    error_messages.sort();
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();

    let mut hours: Vec<(u32, usize)> = hour_counts.iter().map(|(h, c)| (*h, *c)).collect();
    hours.sort_by(|a, b| b.1.cmp(&a.1).then(a.0.cmp(&b.0)));
    if let Some((hour, count)) = hours.first() {
        println!("Busiest Hour: {:02}:00 ({} entries)", hour, count);
    }
}

