import java.io.BufferedReader;
import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws Exception {
        String hostname = runCommand("hostname");
        String os = runCommand("uname -s");
        String architecture = runCommand("uname -m");
        String username = runCommand("whoami");

        StringBuilder sb = new StringBuilder();
        sb.append("{\n");
        sb.append("  \"hostname\": \"").append(escapeJson(hostname)).append("\",\n");
        sb.append("  \"os\": \"").append(escapeJson(os)).append("\",\n");
        sb.append("  \"architecture\": \"").append(escapeJson(architecture)).append("\",\n");
        sb.append("  \"username\": \"").append(escapeJson(username)).append("\"");
        sb.append("\n");
        sb.append("}");

        System.out.println(sb.toString());
    }

    private static String runCommand(String command) throws Exception {
        Process process = Runtime.getRuntime().exec(command);
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        StringBuilder output = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            if (output.length() > 0) {
                output.append("\n");
            }
            output.append(line);
        }
        process.waitFor();
        reader.close();
        return output.toString().trim();
    }

    private static String escapeJson(String s) {
        return s.replace("\\", "\\\\").replace("\"", "\\\"");
    }
}

