            if (output.length() > 0) {
                output.append("\n");
            }
            output.append(line);
        }
        process.waitFor();
        reader.close();
        return output.toString().trim();
    }

    private static String escapeJson(String s) {
        return s.replace("\\", "\\\\").replace("\"", "\\\"");
    }
