fn merge(a: Json, b: Json) -> Json {
    match (&a, &b) {
        (Json::Object(a_map), Json::Object(b_map)) => {
            let mut result = a_map.clone();
            for (key, b_val) in b_map {
                match result.get(key) {
                    Some(a_val) => {
                        result.insert(key.clone(), merge(a_val.clone(), b_val.clone()));
                    }
                    None => {
                        result.insert(key.clone(), b_val.clone());
                    }
                }
            }
            Json::Object(result)
        }
        (Json::Array(a_arr), Json::Array(b_arr)) => {
            let mut result = a_arr.clone();
            for item in b_arr {
                if !result.contains(item) {
                    result.push(item.clone());
                }
            }
            Json::Array(result)
        }
        _ => b,
    }
}

fn escape_string(s: &str) -> String {
