    if n.fract() == 0.0 && n.abs() < 1e15 {
        format!("{}", n as i64)
    } else {
        format!("{}", n)
    }
}

fn to_json(value: &Json, indent: usize) -> String {
    let pad = "  ".repeat(indent);
    let pad_inner = "  ".repeat(indent + 1);
    match value {
        Json::Null => "null".to_string(),
        Json::Bool(b) => b.to_string(),
        Json::Number(n) => format_number(*n),
        Json::String(s) => format!("\"{}\"", escape_string(s)),
        Json::Array(arr) => {
            if arr.is_empty() {
                return "[]".to_string();
            }
            let mut items = Vec::new();
            for item in arr {
                items.push(format!("{}{}", pad_inner, to_json(item, indent + 1)));
            }
            format!("[\n{}\n{}]", items.join(",\n"), pad)
        }
        Json::Object(map) => {
            if map.is_empty() {
                return "{}".to_string();
            }
            let mut items = Vec::new();
            for (key, val) in map {
                items.push(format!(
                    "{}\"{}\": {}",
                    pad_inner,
                    escape_string(key),
                    to_json(val, indent + 1)
                ));
            }
            format!("{{\n{}\n{}}}", items.join(",\n"), pad)
        }
    }
}

fn main() {
    let path_a =
        "<tmp>";
    let path_b =
        "<tmp>";

    let content_a = fs::read_to_string(path_a).expect("Failed to read config_a.json");
    let content_b = fs::read_to_string(path_b).expect("Failed to read config_b.json");

    let mut parser_a = Parser::new(&content_a);
    let a = parser_a.parse();

    let mut parser_b = Parser::new(&content_b);
    let b = parser_b.parse();

    let merged = merge(a, b);

    let output = to_json(&merged, 0);
    println!("{}", output);
}

