import java.io.*;
import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Path root = Paths.get("<tmp>");

        Map<String, List<String[]>> extMap = new TreeMap<>();

        Files.walkFileTree(root, new SimpleFileVisitor<Path>() {
            @Override
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) {
                if (Files.isSymbolicLink(file)) {
                    return FileVisitResult.CONTINUE;
                }

                Path rel = root.relativize(file);
                String relPath = rel.toString().replace('\\', '/');

                String fileName = file.getFileName().toString();
                String ext;
                int lastDot = fileName.lastIndexOf('.');
                if (lastDot > 0) {
                    ext = fileName.substring(lastDot);
                } else {
                    ext = "";
                }

                int lines;
                long chars;
                try {
                    lines = countLines(file);
                    chars = Files.size(file);
                } catch (IOException e) {
                    return FileVisitResult.CONTINUE;
                }

                extMap.computeIfAbsent(ext, k -> new ArrayList<>())
                      .add(new String[]{relPath, String.valueOf(lines), String.valueOf(chars)});

                return FileVisitResult.CONTINUE;
            }

            @Override
            public FileVisitResult visitFileFailed(Path file, IOException exc) {
                return FileVisitResult.CONTINUE;
            }
        });

        for (List<String[]> list : extMap.values()) {
            list.sort(Comparator.comparing(a -> a[0]));
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== File Tree Analysis ===\n");
        sb.append("\n");

        int totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        for (Map.Entry<String, List<String[]>> entry : extMap.entrySet()) {
            String ext = entry.getKey();
            List<String[]> files = entry.getValue();

            int fileCount = files.size();
            long extLines = 0;
            long extChars = 0;

            for (String[] f : files) {
                extLines += Integer.parseInt(f[1]);
                extChars += Long.parseLong(f[2]);
            }

            totalFiles += fileCount;
            totalLines += extLines;
            totalChars += extChars;

            sb.append("Extension: ").append(ext).append("\n");
            sb.append("  Files: ").append(fileCount).append("\n");
            sb.append("  Total Lines: ").append(extLines).append("\n");
            sb.append("  Total Characters: ").append(extChars).append("\n");

            for (String[] f : files) {
                sb.append("    ").append(f[0]).append(": ").append(f[1]).append(" lines, ").append(f[2]).append(" chars\n");
            }
        }

        sb.append("\n");
        sb.append("Total: ").append(totalFiles).append(" files, ").append(totalLines).append(" lines, ").append(totalChars).append(" characters\n");

        System.out.print(sb.toString());
    }

    private static int countLines(Path file) throws IOException {
        int count = 0;
        try (BufferedReader reader = Files.newBufferedReader(file)) {
            while (reader.readLine() != null) {
                count++;
            }
        }
        return count;
    }
}
