    p++;

    while (*p != ']') {
        while (*p == ' ' || *p == ',' || *p == '\n' || *p == '\r' || *p == '\t') p++;
        if (*p == ']') break;
        if (*p != '"') break;
        p++;
        char name[256];
        int i = 0;
        while (*p != '"' && *p != '\0' && i < 255) name[i++] = *p++;
        name[i] = '\0';
        if (*p == '"') p++;
        nodes[num_nodes] = (char *)malloc(i + 1);
        memcpy(nodes[num_nodes], name, i + 1);
        num_nodes++;
    }

    /* Parse edges */
    int num_edges = 0;
    Edge *edges = (Edge *)malloc(sizeof(Edge) * (size_t)(fsize + 10));
    if (!edges) { free(buf); free(nodes); return 1; }

    p = strstr(buf, "\"edges\"");
    if (!p) { free(buf); free(nodes); free(edges); return 1; }
    p = strchr(p, '[');
    if (!p) { free(buf); free(nodes); free(edges); return 1; }
    p++;

    while (*p != ']') {
        while (*p == ' ' || *p == ',' || *p == '\n' || *p == '\r' || *p == '\t') p++;
        if (*p == ']') break;
        if (*p != '{') break;
        p++;

        Edge e;
        memset(&e, 0, sizeof(e));

        while (*p != '}' && *p != '\0') {
            while (*p == ' ' || *p == ',' || *p == '\n' || *p == '\r' || *p == '\t') p++;
            if (*p == '}' || *p == '\0') break;
            if (*p != '"') break;
            p++;
            char key[256];
            int i = 0;
            while (*p != '"' && *p != '\0' && i < 255) key[i++] = *p++;
            key[i] = '\0';
            if (*p == '"') p++;

            while (*p == ' ' || *p == ':') p++;

            if (strcmp(key, "from") == 0) {
                if (*p == '"') {
                    p++;
                    i = 0;
                    while (*p != '"' && *p != '\0' && i < 255) e.from[i++] = *p++;
                    e.from[i] = '\0';
                    if (*p == '"') p++;
                }
            } else if (strcmp(key, "to") == 0) {
                if (*p == '"') {
                    p++;
                    i = 0;
                    while (*p != '"' && *p != '\0' && i < 255) e.to[i++] = *p++;
                    e.to[i] = '\0';
                    if (*p == '"') p++;
                }
            } else if (strcmp(key, "weight") == 0) {
                e.weight = atof(p);
                while (*p != ',' && *p != '}' && *p != '\0' && *p != ' ') p++;
            }
        }
        if (*p == '}') p++;
        edges[num_edges++] = e;
    }

    free(buf);

    /* Build node index lookup */
    int *idx = (int *)malloc(sizeof(int) * (size_t)num_nodes);
    if (!idx) { free(nodes); free(edges); return 1; }

    int source = -1;
    for (int i = 0; i < num_nodes; i++) {
        if (strcmp(nodes[i], "A") == 0) { source = i; break; }
    }
    if (source == -1) {
        fprintf(stderr, "Node A not found\n");
        free(nodes); free(edges); free(idx);
        return 1;
    }

