    for (int i = 0; i < num_nodes; i++) head[i] = -1;

    AdjEdge *adj = (AdjEdge *)malloc(sizeof(AdjEdge) * (size_t)(num_edges * 2));
    int adj_count = 0;

    for (int i = 0; i < num_edges; i++) {
        int from_idx = -1, to_idx = -1;
        for (int j = 0; j < num_nodes; j++) {
            if (strcmp(nodes[j], edges[i].from) == 0) from_idx = j;
            if (strcmp(nodes[j], edges[i].to) == 0) to_idx = j;
        }
        if (from_idx == -1 || to_idx == -1) continue;

        adj[adj_count].to = to_idx;
        adj[adj_count].weight = edges[i].weight;
        adj[adj_count].next = head[from_idx];
        head[from_idx] = adj_count++;

        adj[adj_count].to = from_idx;
        adj[adj_count].weight = edges[i].weight;
        adj[adj_count].next = head[to_idx];
        head[to_idx] = adj_count++;
    }

    /* Dijkstra */
    double *dist = (double *)malloc(sizeof(double) * (size_t)num_nodes);
    int *visited = (int *)malloc(sizeof(int) * (size_t)num_nodes);
    for (int i = 0; i < num_nodes; i++) {
        dist[i] = INFINITY;
        visited[i] = 0;
