        double min_d = INFINITY;
        for (int i = 0; i < num_nodes; i++) {
            if (!visited[i] && dist[i] < min_d) {
                min_d = dist[i];
                u = i;
            }
        }
        if (u == -1) break;
        visited[u] = 1;

        for (int e = head[u]; e != -1; e = adj[e].next) {
            int v = adj[e].to;
            if (!visited[v] && dist[u] + adj[e].weight < dist[v]) {
                dist[v] = dist[u] + adj[e].weight;
            }
        }
    }

    /* Sort node indices alphabetically */
    int *order = (int *)malloc(sizeof(int) * (size_t)num_nodes);
    for (int i = 0; i < num_nodes; i++) order[i] = i;

    for (int i = 0; i < num_nodes - 1; i++) {
        for (int j = 0; j < num_nodes - 1 - i; j++) {
            if (strcmp(nodes[order[j]], nodes[order[j + 1]]) > 0) {
                int tmp = order[j];
                order[j] = order[j + 1];
                order[j + 1] = tmp;
            }
        }
    }

    /* Output */
    printf("=== Shortest Paths from A ===\n\n");
    for (int i = 0; i < num_nodes; i++) {
        int idx_i = order[i];
        if (dist[idx_i] == INFINITY) {
            printf("A -> %s: unreachable\n", nodes[idx_i]);
        } else {
            double d = dist[idx_i];
            if (d == (double)(long long)d) {
                printf("A -> %s: %lld\n", nodes[idx_i], (long long)d);
            } else {
                printf("A -> %s: %g\n", nodes[idx_i], d);
            }
        }
    }

    /* Cleanup */
    for (int i = 0; i < num_nodes; i++) free(nodes[i]);
    free(nodes);
    free(edges);
    free(head);
    free(adj);
    free(dist);
    free(visited);
    free(order);
    free(idx);

    return 0;
}

