import Foundation

let baseDir = "<tmp>"

struct FileEntry {
    let relativePath: String
    let lines: Int
    let chars: Int
}

var fileEntries: [String: [FileEntry]] = [:]
var visitedDirs: Set<String> = []

func isSymlink(_ path: String) -> Bool {
    let attrs = try? FileManager.default.attributesOfItem(atPath: path)
    if let type = attrs?[.type] as? FileAttributeType {
        return type == .typeSymbolicLink
    }
    return false
}

func walkDirectory(_ path: String) {
    let fm = FileManager.default

    if isSymlink(path) { return }
    if visitedDirs.contains(path) { return }
    visitedDirs.insert(path)

    guard let contents = try? fm.contentsOfDirectory(atPath: path) else { return }

    for name in contents {
        let fullPath = path + "/" + name

        if isSymlink(fullPath) { continue }

        var isDir: ObjCBool = false
        guard fm.fileExists(atPath: fullPath, isDirectory: &isDir) else { continue }

        let relPath = fullPath.replacingOccurrences(of: baseDir + "/", with: "")

        if isDir.boolValue {
            walkDirectory(fullPath)
        } else {
            guard let data = fm.contents(atPath: fullPath) else { continue }
            let charCount = data.count

            var lineCount = 0
            if !data.isEmpty {
                var newlines = 0
                for byte in data {
                    if byte == 10 { newlines += 1 }
                }
                if data[data.count - 1] == 10 {
                    lineCount = newlines
                } else {
                    lineCount = newlines + 1
                }
            }

            let ext: String
            if let lastDot = name.lastIndex(of: "."), lastDot != name.startIndex {
                ext = "." + String(name[name.index(after: lastDot)...])
            } else {
                ext = "(no extension)"
            }

            let entry = FileEntry(relativePath: relPath, lines: lineCount, chars: charCount)
            fileEntries[ext, default: []].append(entry)
        }
    }
}

