        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.next();
            return Ok(Json::Array(items));
        }
        loop {
            let val = self.parse_value()?;
            items.push(val);
            self.skip_whitespace();
            match self.next() {
                Some(',') => continue,
                Some(']') => break,
                _ => return Err("Expected ',' or ']'".to_string()),
            }
        }
        Ok(Json::Array(items))
    }

    fn parse_string(&mut self) -> Result<String, String> {
        self.next();
        let mut s = String::new();
        loop {
            match self.next() {
                Some('"') => break,
                Some('\\') => {
                    match self.next() {
                        Some('"') => s.push('"'),
                        Some('\\') => s.push('\\'),
                        Some('/') => s.push('/'),
                        Some('n') => s.push('\n'),
                        Some('t') => s.push('\t'),
                        Some('r') => s.push('\r'),
                        Some('b') => s.push('\u{0008}'),
                        Some('f') => s.push('\u{000C}'),
                        Some('u') => {
                            let mut hex = String::new();
                            for _ in 0..4 {
                                hex.push(self.next().ok_or("bad unicode")?);
                            }
                            let code =
                                u32::from_str_radix(&hex, 16).map_err(|_| "bad unicode")?;
                            s.push(
                                char::from_u32(code)
                                    .ok_or_else(|| "bad unicode".to_string())?,
                            );
                        }
                        _ => return Err("bad escape".to_string()),
                    }
                }
                Some(c) => s.push(c),
                None => return Err("unterminated string".to_string()),
            }
        }
        Ok(s)
    }

    fn parse_number(&mut self) -> Result<Json, String> {
        let mut s = String::new();
        if self.peek() == Some('-') {
            s.push('-');
            self.next();
        }
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() || c == '.' || c == 'e' || c == 'E' {
                s.push(c);
                self.next();
            } else if (c == '+' || c == '-') && s.contains(['e', 'E']) {
                s.push(c);
                self.next();
            } else {
                break;
            }
        }
        s.parse::<f64>()
            .map(Json::Number)
            .map_err(|e| e.to_string())
    }
}

fn main() {
    let path =
        "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read file");
    let json = Parser::new(&content)
        .parse_value()
        .expect("Failed to parse JSON");

    let nodes_json = json.get("nodes").expect("No 'nodes' key");
    let nodes_arr = nodes_json.as_array().expect("'nodes' is not an array");
    let node_list: Vec<String> = nodes_arr
        .iter()
        .map(|n| n.as_str().unwrap().to_string())
        .collect();

    let edges_json = json.get("edges").expect("No 'edges' key");
    let edges_arr = edges_json.as_array().expect("'edges' is not an array");

    let mut adj: BTreeMap<String, Vec<(String, u64)>> = BTreeMap::new();
    for node in &node_list {
        adj.insert(node.clone(), vec![]);
    }

    for edge in edges_arr {
        let from = edge.get("from").unwrap().as_str().unwrap().to_string();
        let to = edge.get("to").unwrap().as_str().unwrap().to_string();
        let weight = edge.get("weight").unwrap().as_f64().unwrap() as u64;
        adj.entry(from.clone())
            .or_default()
            .push((to.clone(), weight));
        adj.entry(to).or_default().push((from, weight));
    }

    let start = "A".to_string();
    let mut dist: BTreeMap<String, u64> = BTreeMap::new();
    for node in &node_list {
        dist.insert(node.clone(), u64::MAX);
    }
    dist.insert(start.clone(), 0);

    let mut heap: BinaryHeap<Reverse<(u64, String)>> = BinaryHeap::new();
    heap.push(Reverse((0, start.clone())));

    while let Some(Reverse((d, node))) = heap.pop() {
        if d > dist[&node] {
            continue;
        }
        if let Some(neighbors) = adj.get(&node) {
            for (neighbor, weight) in neighbors {
                let new_dist = d + weight;
                if new_dist < dist[neighbor] {
                    dist.insert(neighbor.clone(), new_dist);
                    heap.push(Reverse((new_dist, neighbor.clone())));
                }
            }
        }
    }

    let mut sorted_nodes = node_list.clone();
    sorted_nodes.sort();

    println!("=== Shortest Paths from A ===");
    println!();
    for node in &sorted_nodes {
        println!("A -> {}: {}", node, dist[node]);
    }
}
