        let ext_chars: u64 = file_list.iter().map(|f| f.2).sum();

        total_files += n_files;
        total_lines += ext_lines;
        total_chars += ext_chars;

        print!("Extension: {}\n", ext);
        print!("  Files: {}\n", n_files);
        print!("  Total Lines: {}\n", ext_lines);
        print!("  Total Characters: {}\n", ext_chars);

        for (rel_path, lines, chars) in file_list {
            print!("    {}: {} lines, {} chars\n", rel_path, lines, chars);
        }
    }

    print!("\n");
    print!("Total: {} files, {} lines, {} characters\n", total_files, total_lines, total_chars);
}

fn walk(dir: &Path, root: &Path, files: &mut BTreeMap<String, Vec<(String, u64, u64)>>) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };

    for entry in entries {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };

        let file_type = match entry.file_type() {
            Ok(ft) => ft,
            Err(_) => continue,
        };

        if file_type.is_symlink() {
            continue;
        }

        let path = entry.path();

        if file_type.is_dir() {
            walk(&path, root, files);
        } else if file_type.is_file() {
            let rel_path = path
                .strip_prefix(root)
                .unwrap()
                .to_string_lossy()
                .replace('\\', "/");

            let ext = path
                .extension()
                .map(|e| format!(".{}", e))
                .unwrap_or_else(|| String::new());

            let (lines, chars) = read_file_stats(&path);

            files.entry(ext).or_default().push((rel_path, lines, chars));
        }
    }
}

fn read_file_stats(path: &Path) -> (u64, u64) {
    let mut contents = Vec::new();
    match fs::File::open(path) {
        Ok(mut file) => {
            if file.read_to_end(&mut contents).is_err() {
                return (0, 0);
            }
        }
        Err(_) => return (0, 0),
    }

    let chars = contents.len() as u64;

    let mut lines = contents.iter().filter(|&&b| b == b'\n').count() as u64;
    if !contents.is_empty() && contents[contents.len() - 1] != b'\n' {
        lines += 1;
    }

    (lines, chars)
}

