fn det(m: &Vec<Vec<i64>>) -> i64 {
    let n = m.len();
    if n == 1 {
        return m[0][0];
    }
    let mut result = 0;
    for j in 0..n {
        let sign = if j % 2 == 0 { 1 } else { -1 };
        let minor: Vec<Vec<i64>> = (1..n)
            .map(|row| {
                (0..n)
                    .filter(|&col| col != j)
                    .map(|col| m[row][col])
                    .collect()
            })
            .collect();
        result += sign * m[0][j] * det(&minor);
    }
    result
}

