static char *http_get(const char *host, int port, const char *path) {
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) return NULL;

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons((unsigned short)port);
    if (inet_pton(AF_INET, host, &addr.sin_addr) != 1) {
        close(fd);
        return NULL;
    }

    if (connect(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        close(fd);
        return NULL;
    }

    char request[512];
    int rlen = snprintf(request, sizeof(request),
        "GET %s HTTP/1.1\r\nHost: %s:%d\r\nConnection: close\r\n\r\n",
        path, host, port);

    if (send(fd, request, (size_t)rlen, 0) < 0) {
        close(fd);
        return NULL;
    }

    size_t cap = 1024 * 1024;
    char *buf = (char *)malloc(cap);
    if (!buf) { close(fd); return NULL; }

    int total = 0;
    int n;
    while ((n = (int)recv(fd, buf + total, cap - (size_t)total - 1, 0)) > 0) {
        total += n;
        if ((size_t)total + 1 >= cap) {
            cap *= 2;
            buf = (char *)realloc(buf, cap);
            if (!buf) { close(fd); return NULL; }
        }
    }
    buf[total] = '\0';
    close(fd);

    char *body = strstr(buf, "\r\n\r\n");
    char *result;
    if (body) {
        body += 4;
        int blen = (int)(buf + total - body);
        result = (char *)malloc((size_t)blen + 1);
        if (result) {
            memcpy(result, body, (size_t)blen);
            result[blen] = '\0';
        }
    } else {
        result = NULL;
    }
    free(buf);
    return result;
}

static char *json_extract_string(const char *s) {
    s++; /* skip opening quote */
    const char *start = s;
    while (*s && *s != '"') {
        if (*s == '\\') s++;
